import{_ as o}from"./chunks/settings-gamepad.pc.ko.BNw-kDrv.js";import{_ as e,o as a,c as r,a5 as s}from"./chunks/framework.BjM_ivYE.js";const m=JSON.parse('{"title":"조이스틱 무반응","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/joystick-not-working.md","filePath":"ko/manual/troubleshooting/joystick-not-working.md","lastUpdated":1789971982000}'),n={name:"ko/manual/troubleshooting/joystick-not-working.md"};function i(d,t,l,c,h,p){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="조이스틱-무반응" tabindex="-1">조이스틱 무반응 <a class="header-anchor" href="#조이스틱-무반응" aria-label="Permalink to &quot;조이스틱 무반응&quot;">​</a></h1><p>앉기 · 서기 같은 버튼은 정상 동작하는데 스틱을 움직여도 로봇이 반응하지 않는 경우입니다. 대부분 <strong>조종 권한이 다른 쪽에 있거나</strong>, 앱이 게임패드를 잡지 못한 경우입니다.</p><h2 id="first-checks" tabindex="-1">먼저 확인할 것 <a class="header-anchor" href="#first-checks" aria-label="Permalink to &quot;먼저 확인할 것 {#first-checks}&quot;">​</a></h2><p><strong>앱 설정 → 게임패드</strong>를 엽니다. 맨 위 상태 줄이 지금 상황을 그대로 알려 줍니다.</p><p><img src="'+o+'" alt="게임패드 설정"></p><table tabindex="0"><thead><tr><th>상태 줄</th><th>뜻</th><th>할 일</th></tr></thead><tbody><tr><td><code>연결됨</code> + 기기 이름</td><td>패드를 잡고 있습니다</td><td>아래 <a href="#ownership">제어권</a>으로 넘어가세요</td></tr><tr><td><code>연결된 게임패드 없음 — 가상 조이스틱 사용 중</code></td><td>패드를 못 잡았습니다</td><td>아래 <a href="#not-detected">패드 인식</a>을 보세요</td></tr></tbody></table><p><code>적용 프로파일:</code>이 엉뚱한 기기를 가리키면 스틱 배치가 어긋나 조작이 이상하게 먹습니다 — <strong>앱 설정 → 게임패드</strong>의 <code>매핑 마법사</code>로 이 기기 전용 프로파일을 만드세요(<a href="/RBQ/ko/manual/gui/developer-mode.html">개발자 모드</a> 필요).</p><h2 id="not-detected" tabindex="-1">패드가 인식되지 않습니다 <a class="header-anchor" href="#not-detected" aria-label="Permalink to &quot;패드가 인식되지 않습니다 {#not-detected}&quot;">​</a></h2><ul><li><strong>버튼을 한 번 누르세요.</strong> 브라우저·데스크탑 빌드는 개인정보 규칙상 <strong>버튼을 눌러야 기기를 노출</strong>합니다. 스틱만 움직이는 것으로는 인식되지 않습니다 — 가장 흔한 오판입니다.</li><li><strong>USB·블루투스 연결을 다시 맺습니다.</strong> 연결하면 앱이 즉시 인식해 가상 조이스틱을 숨깁니다.</li><li><strong>조이스틱 모드를 확인합니다.</strong> <code>조이스틱 모드</code>가 <code>가상 조이스틱</code>으로 지정돼 있으면 패드가 붙어 있어도 화면은 가상 조이스틱으로 남습니다. <code>자동</code>으로 되돌리세요. 제어 홈 왼쪽 카드의 <code>조종</code> 팝오버에도 같은 선택이 있습니다.</li><li><strong>Steam Deck</strong>은 <strong>게이밍 모드</strong>(또는 Steam 클라이언트 경유)로 실행해야 내장 패드가 앱에 보입니다. 데스크탑 모드에서 직접 실행하면 패드가 마우스·키보드로 흉내 내져 앱에 잡히지 않습니다.</li></ul><h2 id="ownership" tabindex="-1">화면 표시는 움직이는데 로봇이 반응하지 않습니다 <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;화면 표시는 움직이는데 로봇이 반응하지 않습니다 {#ownership}&quot;">​</a></h2><p><strong>원인:</strong> 조종 권한(소유권)이 다른 기기에 있습니다. 로봇은 한 번에 한 기기의 입력만 받습니다.</p><p><strong>해결:</strong> 다른 기기가 쥐고 있으면 약 1초 뒤 화면 전체를 덮는 <code>다른 컨트롤러가 제어 중입니다</code> 가림막이 뜹니다 — <strong><code>제어권 가져오기</code></strong> 를 누르면 넘어옵니다. 가림막이 뜨지 않았다면 상단 바의 상태 칩을 눌러 <strong>시스템 종합 상태</strong>의 <strong>소유권</strong> 행을 보세요. <code>가져오기 ▸</code>가 보이면 이 기기가 소유자가 아니라는 뜻입니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p><strong>앱 설정 → 게임패드</strong>의 <code>외부 조종 (SLAM·SDK)</code>가 켜져 있으면 로봇이 외부 프로그램의 명령을 따르므로 조이스틱 입력이 무시됩니다. 이 경우 상단 상태 칩에 <code>SLAM</code> 이 표시됩니다. (<a href="/RBQ/ko/manual/gui/developer-mode">개발자 모드</a>에서만 보이는 설정입니다.)</p></div></div><h2 id="input-timeout" tabindex="-1">조작 중에 로봇이 갑자기 멈춥니다 <a class="header-anchor" href="#input-timeout" aria-label="Permalink to &quot;조작 중에 로봇이 갑자기 멈춥니다 {#input-timeout}&quot;">​</a></h2><p><strong>원인:</strong> 조이스틱 입력이 <strong>1초 이상</strong> 도착하지 않으면 로봇은 안전을 위해 모든 조작 입력을 0으로 처리합니다. 무선이 순간적으로 끊기면 로봇이 그 자리에서 멈춥니다.</p><p><strong>해결:</strong> 로봇과의 거리를 좁히고 사이에 금속 구조물이나 벽이 없도록 합니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>이 동작은 고장이 아니라 안전 기능입니다. 조종 신호가 끊긴 상태로 로봇이 계속 움직이지 않도록 설계되어 있습니다.</p></div></div><h2 id="buttons" tabindex="-1">스틱은 되는데 버튼이 안 먹습니다 <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;스틱은 되는데 버튼이 안 먹습니다 {#buttons}&quot;">​</a></h2><p>기본값에서 앱은 스틱과 <strong>L1 · R1</strong> 두 개만 로봇에 전달합니다. 나머지 버튼은 실수로 눌러도 로봇 동작이 나가지 않도록 일부러 빼 둔 것입니다 — 고장이 아닙니다.</p><p>버튼에 동작을 붙이려면 <strong>앱 설정 → 게임패드</strong>의 <code>버튼 매핑</code>을 쓰거나, <a href="/RBQ/ko/manual/gui/developer-mode.html">개발자 모드</a>에서 <code>전체 버튼 전송</code>을 켜세요. 자세한 내용은 <a href="/RBQ/ko/manual/gui/gamepad.html">게임패드</a>에 있습니다.</p><h2 id="stair-mode" tabindex="-1">계단 모드에서만 움직이지 않습니다 <a class="header-anchor" href="#stair-mode" aria-label="Permalink to &quot;계단 모드에서만 움직이지 않습니다 {#stair-mode}&quot;">​</a></h2><p><strong>원인:</strong> 계단 모드는 카메라 데이터를 기반으로 동작합니다. 카메라 영상이 나오지 않으면 조이스틱이 동작하지 않는 것처럼 보일 수 있습니다.</p><p><strong>해결:</strong> 먼저 <a href="/RBQ/ko/manual/troubleshooting/no-camera-view.html">카메라 영상이 나오지 않을 때</a>를 확인해 영상이 정상적으로 나오는지 점검하세요.</p><p>영상은 정상인데 계단 모드에서만 움직이지 않는다면 <a href="/RBQ/ko/manual/troubleshooting/stair-mode-not-moving.html">계단 모드에서 움직이지 않을 때</a>를 확인하세요.</p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p><strong><a href="/RBQ/ko/manual/gui/logs.html#real-time">로그 → Real Time</a></strong> 에서 조작할 때 관련 메시지가 올라오는지 확인한 뒤, <strong>앱 설정 → 게임패드</strong>의 상태 줄에 무엇이 표시됐는지 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',27)])])}const b=e(n,[["render",i]]);export{m as __pageData,b as default};
